import os
import shutil
from celery import Celery
from celery.utils.log import get_task_logger
import ldclient
from ldclient.config import Config as LDConfig
from ldclient import Context

app = Celery('document_processor', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))
logger = get_task_logger(__name__)

# LaunchDarkly initialization
ld_sdk_key = os.environ.get('LAUNCHDARKLY_SDK_KEY', '')
if ld_sdk_key:
    ldclient.set_config(LDConfig(ld_sdk_key))

BASE_STORAGE_DIR = '/var/app/documents'
ARCHIVE_DIR = '/var/app/archive'


def get_ld_client():
    return ldclient.get()


def resolve_document_path(tenant_id, document_name):
    """Resolve the full path for a tenant document."""
    # Construct path from tenant and document name
    full_path = os.path.join(BASE_STORAGE_DIR, tenant_id, document_name)
    return full_path


def resolve_document_path_safe(tenant_id, document_name):
    """Resolve path with canonicalization check."""
    base = os.path.join(BASE_STORAGE_DIR, tenant_id)
    full_path = os.path.realpath(os.path.join(base, document_name))
    if not full_path.startswith(os.path.realpath(base)):
        raise ValueError(f"Path traversal detected: {document_name}")
    return full_path


@app.task(bind=True, max_retries=3)
def process_document_archive(self, tenant_id, document_name, user_id, operation='archive'):
    """
    Background job to archive or process tenant documents.
    Supports legacy path resolution and new safe resolution based on feature flag.
    """
    logger.info(f"Processing document archive: tenant={tenant_id}, doc={document_name}, user={user_id}")

    try:
        client = get_ld_client()
        context = Context.builder(user_id).kind('user').set('tenant', tenant_id).build()

        # Feature flag: use_safe_path_resolution
        # When True: uses canonicalized path resolution
        # When False: uses legacy direct path join (vulnerable)
        use_safe_resolution = client.variation('use-safe-path-resolution', context, False)

        if use_safe_resolution:
            resolved_path = resolve_document_path_safe(tenant_id, document_name)
            logger.info(f"Using safe path resolution for {tenant_id}")
        else:
            resolved_path = resolve_document_path(tenant_id, document_name)
            logger.info(f"Using legacy path resolution for {tenant_id}")

        if not os.path.exists(resolved_path):
            logger.warning(f"Document not found: {resolved_path}")
            return {'status': 'not_found', 'path': document_name}

        if operation == 'archive':
            archive_dest = os.path.join(ARCHIVE_DIR, tenant_id, os.path.basename(document_name))
            os.makedirs(os.path.dirname(archive_dest), exist_ok=True)
            shutil.copy2(resolved_path, archive_dest)
            logger.info(f"Archived document to {archive_dest}")
            return {'status': 'archived', 'destination': archive_dest}

        elif operation == 'read':
            with open(resolved_path, 'r') as f:
                content = f.read()
            return {'status': 'success', 'content': content, 'size': len(content)}

        elif operation == 'delete':
            os.remove(resolved_path)
            logger.info(f"Deleted document: {resolved_path}")
            return {'status': 'deleted'}

        else:
            return {'status': 'error', 'message': f'Unknown operation: {operation}'}

    except ValueError as e:
        logger.error(f"Security violation: {e}")
        return {'status': 'error', 'message': 'Invalid path'}
    except Exception as e:
        logger.error(f"Error processing document: {e}")
        self.retry(countdown=60)


@app.task
def bulk_archive_documents(tenant_id, document_list, user_id):
    """Queue multiple documents for archival."""
    results = []
    for doc_name in document_list:
        result = process_document_archive.delay(tenant_id, doc_name, user_id, 'archive')
        results.append(result.id)
    return {'queued': len(results), 'task_ids': results}
